mapper.select:
SELECT check_card_award_state_id, user_id, last_awarded_year_month
FROM check_card_award_state
WHERE user_id = #{userId}

mapper.insert:
INSERT INTO check_card_award_state (
    user_id, last_awarded_year_month
) VALUES (
    #{userId}, #{lastAwardedYearMonth}
)
ON DUPLICATE KEY UPDATE
    last_awarded_year_month = VALUES(last_awarded_year_month)
